#!/usr/bin/env node
/**
 * Generates typed copies of packages/markets/markets.json for every consumer.
 * Docker build contexts are per service, so services cannot import a workspace package;
 * each one gets a generated file instead, and CI fails if any copy is stale.
 *
 *   node packages/markets/build.mjs          # write outputs
 *   node packages/markets/build.mjs --check  # CI: fail if outputs are stale or data is invalid
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const data = JSON.parse(readFileSync(join(here, 'markets.json'), 'utf8'));
const HEADER = 'GENERATED by packages/markets/build.mjs from markets.json — do not edit by hand.';

// ---- Validation: a typo here would silently block or allow SMS to a whole country ----------
const errors = [];
const codes = new Set();
const callingCodes = new Set();
for (const m of data.markets) {
  if (!/^[A-Z]{2}$/.test(m.code)) errors.push(`${m.code}: code must be ISO 3166-1 alpha-2`);
  if (codes.has(m.code)) errors.push(`${m.code}: duplicate market`);
  codes.add(m.code);
  if (!/^[1-9]\d{0,2}$/.test(m.callingCode)) errors.push(`${m.code}: callingCode must be 1-3 digits without +`);
  callingCodes.add(m.callingCode);
  if (!data.currencies[m.currency]) errors.push(`${m.code}: unknown currency ${m.currency}`);
  if (!Number.isInteger(m.wave) || m.wave < 1) errors.push(`${m.code}: wave must be a positive integer`);
  if (!m.offerSources.includes('local_stores')) errors.push(`${m.code}: local_stores must be an offer source everywhere`);
}
// ITU calling codes are prefix-free; if two configured codes overlap, prefix matching breaks.
for (const a of callingCodes) for (const b of callingCodes) {
  if (a !== b && b.startsWith(a)) errors.push(`calling code ${a} is a prefix of ${b}`);
}
for (const [code, c] of Object.entries(data.currencies)) {
  if (!/^[A-Z]{3}$/.test(code)) errors.push(`${code}: currency must be ISO 4217`);
  if (![0, 2, 3].includes(c.minorUnits)) errors.push(`${code}: minorUnits must be 0, 2 or 3`);
  for (const lang of ['ar', 'en', 'tr']) if (!c[lang]) errors.push(`${code}: missing ${lang} name`);
}
if (errors.length) {
  console.error(errors.map((e) => `✗ ${e}`).join('\n'));
  process.exit(1);
}

const markets = data.markets.map(({ code, wave, region, callingCode, currency, locales }) => ({ code, wave, region, callingCode, currency, locales }));
const currencyNamesAr = Object.fromEntries(Object.entries(data.currencies).map(([k, v]) => [k, v.ar]));
const minorUnits = Object.fromEntries(Object.entries(data.currencies).map(([k, v]) => [k, v.minorUnits]));

const ts = `// ${HEADER}
export interface Market {
  code: string;
  wave: number;
  region: string;
  callingCode: string;
  currency: string;
  locales: string[];
}

export const MARKETS: readonly Market[] = ${JSON.stringify(markets, null, 2)};

/** Arabic currency unit names (a word, not a symbol: "US$" is reordered inside RTL text). */
export const CURRENCY_NAMES_AR: Readonly<Record<string, string>> = ${JSON.stringify(currencyNamesAr, null, 2)};

/** ISO 4217 minor units: KWD/BHD/OMR/TND/IQD have 3 decimals, JPY/KRW none. */
export const CURRENCY_MINOR_UNITS: Readonly<Record<string, number>> = ${JSON.stringify(minorUnits, null, 2)};
`;

const dartMap = Object.entries(currencyNamesAr).map(([k, v]) => `  '${k}': '${v}',`).join('\n');
const dart = `// ${HEADER}

/// Arabic currency unit names (a word, not a symbol: "US$" is reordered inside RTL text).
const Map<String, String> currencyNamesAr = {
${dartMap}
};
`;

const outputs = [
  [join(root, 'services/auth-service/src/common/markets.generated.ts'), ts],
  [join(root, 'services/listings-service/src/common/markets.generated.ts'), ts],
  [join(root, 'apps/web/src/lib/markets.generated.ts'), ts],
  [join(root, 'apps/mobile/lib/core/utils/markets.g.dart'), dart],
];

const check = process.argv.includes('--check');
let stale = false;
for (const [path, content] of outputs) {
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (current === content) continue;
  if (check) {
    stale = true;
    console.error(`✗ ${path.replace(root + '/', '')} is stale — run: npm run markets:build`);
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${path.replace(root + '/', '')}`);
  }
}
if (stale) process.exit(1);
console.log(`✓ ${data.markets.length} markets, ${Object.keys(data.currencies).length} currencies`);
